options.onRender:
(function(){
try{
  function valuesToArray(values){
    if(!values)return[];
    if(Array.isArray(values))return values;
    if(typeof values.toArray==='function')return values.toArray();
    var out=[];
    for(var i=0;i<(values.length||0);i++)out.push(typeof values.get==='function'?values.get(i):values[i]);
    return out;
  }
  function clean(value){return String(value==null?'':value).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]});}
  var current=typeof getTemplateSrv==='function'?getTemplateSrv().replace('$app_name'):'';
  var names=[];
  ((data&&data.series)||[]).forEach(function(frame){
    if(frame.refId!=='A')return;
    var fields=frame.fields||[];
    for(var i=0;i<fields.length;i++){
      var labels=fields[i].labels||{};
      if(labels.app)names.push(String(labels.app));
    }
  });
  if(typeof getTemplateSrv==='function'){
    var variable=(getTemplateSrv().getVariables()||[]).find(function(item){return item.name==='app_name'});
    ((variable&&variable.options)||[]).forEach(function(option){
      if(option&&option.value&&option.value!=='$__all')names.push(String(option.value));
    });
  }
  if(current&&current.indexOf('$')!==0)names.push(current);
  names=names.filter(Boolean).filter(function(name,index,list){return list.indexOf(name)===index}).sort();
  var title=htmlNode.querySelector('#header-app');
  if(title)title.textContent=current||'Spring Boot Operations';
  var select=htmlNode.querySelector('#app-select');
  if(select){
    if(names.length){
      select.innerHTML=names.map(function(name){return'<option value="'+clean(name)+'" '+(name===current?'selected':'')+'>'+clean(name)+'</option>'}).join('');
      select.onchange=function(){
        var url=new URL(window.location.href);
        url.searchParams.set('var-app_name',select.value);
        window.location.assign(url.toString());
      };
    }else{
      select.innerHTML='<option value="">Nenhuma aplicação encontrada</option>';
      select.disabled=true;
    }
  }
  var fresh=htmlNode.querySelector('#fresh-time'),now=new Date();
  if(fresh)fresh.textContent='Atualizado '+String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');
}catch(error){}
})();

