options.onRender:
function arr(values){if(!values)return[];if(Array.isArray(values))return values;if(typeof values.toArray==='function')return values.toArray();var out=[];for(var i=0;i<(values.length||0);i++)out.push(typeof values.get==='function'?values.get(i):values[i]);return out}
function numField(frame){var fs=(frame&&frame.fields)||[];for(var i=0;i<fs.length;i++){if(fs[i].type==='number'||fs[i].name==='Value'||fs[i].name==='value')return fs[i]}return fs.length>1?fs[1]:fs[0]}
function timeField(frame){var fs=(frame&&frame.fields)||[];for(var i=0;i<fs.length;i++){if(fs[i].type==='time'||fs[i].name==='Time'||fs[i].name==='time')return fs[i]}return fs[0]}
function frames(ref){return((data&&data.series)||[]).filter(function(f){return f.refId===ref})}
function last(ref){var fs=frames(ref);for(var i=0;i<fs.length;i++){var f=numField(fs[i]),vs=arr(f&&f.values);for(var j=vs.length-1;j>=0;j--){var n=Number(vs[j]);if(Number.isFinite(n))return n}}return null}
function labelOf(frame,key,fallback){var f=numField(frame),ls=(f&&f.labels)||{};if(key&&ls[key]!=null)return String(ls[key]);if(frame&&frame.name)return String(frame.name);if(f&&f.config&&f.config.displayNameFromDS)return String(f.config.displayNameFromDS);return fallback||'série'}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function fmt(n,d){if(!Number.isFinite(n))return'--';return n.toLocaleString('pt-BR',{maximumFractionDigits:d==null?2:d})}
function pct(n){return Number.isFinite(n)?fmt(n,2)+'%':'--'}
function ms(n){return Number.isFinite(n)?fmt(n,n>=100?0:1)+' ms':'--'}
function rate(n){return Number.isFinite(n)?fmt(n,2)+'/s':'--'}
function dur(n){if(!Number.isFinite(n))return'--';n=Math.max(0,n);if(n<60)return Math.round(n)+'s';if(n<3600)return Math.floor(n/60)+'m '+Math.round(n%60)+'s';if(n<86400)return Math.floor(n/3600)+'h '+Math.round((n%3600)/60)+'m';return Math.floor(n/86400)+'d '+Math.round((n%86400)/3600)+'h'}
var palette=['#38bdf8','#f97316','#22c55e','#a78bfa','#f59e0b','#ef4444','#2dd4bf','#fb7185','#60a5fa','#c084fc'];
function emptyHtml(title,sub){return'<div class="empty"><div><b>'+esc(title)+'</b>'+esc(sub||'')+'</div></div>'}
function drawLines(id,ref,key,unitFn){var host=htmlNode.querySelector('#'+id);if(!host)return;var fs=frames(ref),series=[];fs.forEach(function(frame,idx){var vf=numField(frame),tf=timeField(frame),ys=arr(vf&&vf.values).map(Number),xs=arr(tf&&tf.values).map(Number);var pts=[];for(var i=0;i<ys.length;i++){if(Number.isFinite(ys[i]))pts.push({x:Number.isFinite(xs[i])?xs[i]:i,y:ys[i]})}if(pts.length)series.push({name:labelOf(frame,key,'Série '+(idx+1)),pts:pts,color:palette[idx%palette.length]})});if(!series.length){host.innerHTML=emptyHtml('Sem dados','A métrica ainda não foi publicada para esta aplicação.');return}var all=[];series.forEach(function(s){all=all.concat(s.pts)});var xmin=Math.min.apply(null,all.map(function(p){return p.x})),xmax=Math.max.apply(null,all.map(function(p){return p.x})),ymax=Math.max.apply(null,all.map(function(p){return p.y}));if(xmax===xmin)xmax=xmin+1;if(!Number.isFinite(ymax)||ymax<=0)ymax=1;var W=760,H=190,L=34,R=10,T=10,B=23;var sx=function(x){return L+(x-xmin)/(xmax-xmin)*(W-L-R)},sy=function(y){return T+(1-y/ymax)*(H-T-B)};var grid='';for(var g=0;g<4;g++){var gy=T+g*(H-T-B)/3;grid+='<line x1="'+L+'" y1="'+gy+'" x2="'+(W-R)+'" y2="'+gy+'" stroke="#203044" stroke-width="1"/><text x="'+(L-5)+'" y="'+(gy+3)+'" text-anchor="end" fill="#62748a" font-size="8">'+esc(unitFn?unitFn(ymax*(1-g/3)):fmt(ymax*(1-g/3),1))+'</text>'}var paths='';series.forEach(function(s){var d=s.pts.map(function(p,i){return(i?'L':'M')+sx(p.x).toFixed(1)+' '+sy(p.y).toFixed(1)}).join(' ');paths+='<path d="'+d+'" fill="none" stroke="'+s.color+'" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>'});var legend='<div class="legend">'+series.slice(0,10).map(function(s){var v=s.pts[s.pts.length-1].y;return'<div class="legend-item"><i class="legend-dot" style="background:'+s.color+'"></i><span class="legend-name">'+esc(s.name)+'</span><b>'+esc(unitFn?unitFn(v):fmt(v,2))+'</b></div>'}).join('')+'</div>';host.innerHTML='<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" aria-label="gráfico"><defs><linearGradient id="fade-'+id+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#38bdf8" stop-opacity=".16"/><stop offset="1" stop-color="#38bdf8" stop-opacity="0"/></linearGradient></defs>'+grid+paths+'</svg>'+legend}
function drawRank(id,ref,key,unitFn,accent){var host=htmlNode.querySelector('#'+id);if(!host)return;var rows=[];frames(ref).forEach(function(frame,idx){var f=numField(frame),vs=arr(f&&f.values),n=null;for(var i=vs.length-1;i>=0;i--){var v=Number(vs[i]);if(Number.isFinite(v)){n=v;break}}if(n!=null)rows.push({name:labelOf(frame,key,'Item '+(idx+1)),value:n})});rows.sort(function(a,b){return b.value-a.value});if(!rows.length){host.innerHTML=emptyHtml('Sem dados','Nenhuma série encontrada no período.');return}var max=Math.max.apply(null,rows.map(function(r){return Math.abs(r.value)}))||1;host.innerHTML='<div class="rank scroll">'+rows.slice(0,14).map(function(r){var w=Math.max(1,Math.abs(r.value)/max*100);return'<div class="rank-row" title="'+esc(r.name)+'"><span class="rank-name">'+esc(r.name)+'</span><span class="rank-track"><i class="rank-fill" style="width:'+w+'%;--accent:'+(accent||'#38bdf8')+'"></i></span><span class="rank-val">'+esc(unitFn?unitFn(r.value):fmt(r.value,2))+'</span></div>'}).join('')+'</div>'}
(function(){try{function put(id,text,cls){var e=htmlNode.querySelector('#'+id);if(e){e.textContent=text;e.className='value '+(cls||'')}}function state(cardId,value,okText,badText){var c=htmlNode.querySelector('#'+cardId);var good=value===1;if(c)c.style.setProperty('--accent',good?'#22c55e':'#ef4444');return'<span class="status-dot"></span>'+(good?okText:badText)}var a=last('A'),b=last('B'),c=last('C'),d=last('D'),e=last('E'),f=last('F'),g=last('G'),h=last('H');put('v-app',a===1?'● ONLINE':a===0?'● OFFLINE':'SEM DADO',a===1?'ok':a===0?'bad':'warn');put('v-edge',b===1?'● OK':b===0?'● FALHA':'SEM DADO',b===1?'ok':b===0?'bad':'warn');put('v-rate',rate(c),'neutral');put('v-4xx',pct(d),d>=15?'bad':d>=5?'warn':'ok');put('v-5xx',pct(e),e>=2?'bad':e>=.5?'warn':'ok');put('v-p95',ms(f),f>=1000?'bad':f>=500?'warn':'ok');put('v-logs',rate(g),g>=.2?'bad':g>=.05?'warn':'ok');put('v-uptime',dur(h),'')}catch(e){}})();

