rowsHtml+="<tr class='"+rowClass+"'><td class='cell-host'>"+escapeHtml(r.origem)+"</td><td><span class='severity-badge "+meta.cls+"'>"+escapeHtml(r.severity)+"</span></td><td class='cell-trace' title='"+escapeHtml(r.traceId)+"'>"+escapeHtml(r.traceId)+"</td><td class='cell-problem'><div class='cell-problem-wrap'><span class='cell-problem-text'>"+escapeHtml(r.mensagem)+"</span><button class='copy-log-btn' type='button' title='Copiar linha do log' data-idx='"+idx+"'>"+CSV_ICON+"</button></div></td><td>"+formatAge(r.time)+"</td><td>"+formatHora(r.time)+"</td></tr>";
});
if(!rowsHtml){
rowsHtml="<tr class='problems-empty-row'><td colspan='6'>Nenhum log encontrado para os filtros selecionados.</td></tr>";
}
var filterButtonsHtml="<button class='filter-btn filter-btn-severity "+(state.activeSeverity==='all'?'active':'')+"' data-sev='all' type='button'>All</button>";
filterButtonsHtml+=SEV_ORDER.map(function(sv){
var meta=SEV_META[sv];
return "<button class='filter-btn filter-btn-severity btn-"+sv+" "+(state.activeSeverity===sv?'active':'')+"' data-sev='"+sv+"' type='button'>"+meta.label+"</button>";
}).join('');
rightContainer.innerHTML =
"<div class='log-section-header'><div class='log-section-header-left'><span class='log-section-icon'><span class='svg-icon' aria-hidden='true'>"+TABLE_ICON+"</span></span><div><div class='log-section-title'>Logs da Aplicação</div><div class='log-section-sub'>Busca detalhada por nível e conteúdo</div></div></div></div>"+
"<div class='problems-table-panel'>"+
"<div class='filter-bar'>"+
"<div class='filter-group'><span class='filter-label'>Nível:</span>"+filterButtonsHtml+"</div>"+
"<div class='search-bar-group'>"+
"<div class='search-input-wrapper'><span class='svg-icon' aria-hidden='true'>"+SEARCH_ICON+"</span>"+
"<input type='text' id='problem-search-input' class='search-input' placeholder='Buscar origem, traceId ou mensagem...' value='"+escapeHtml(state.searchTerm)+"'/></div>"+
"<button class='pagination-btn export-btn' id='btn-export' type='button' title='Exportar CSV'><span class='svg-icon' aria-hidden='true'>"+CSV_ICON+"</span></button>"+
"</div></div>"+
"<div class='table-wrapper'><table class='problems-table'><thead><tr><th>Origem</th><th>Nível</th><th>TraceId</th><th>Mensagem</th><th>Idade</th><th>Hora</th></tr></thead><tbody>"+rowsHtml+"</tbody></table></div>"+
"<div class='pagination-controls'><span class='pagination-info'>Pagina "+state.currentPage+" de "+totalPages+" &middot; "+filtered.length+" log(s)</span>"+
"<div class='pagination-buttons'>"+
"<button class='pagination-btn' id='btn-prev' type='button' "+(state.currentPage===1?'disabled':'')+">Anterior</button>"+
"<button class='pagination-btn' id='btn-next' type='button' "+(state.currentPage===totalPages?'disabled':'')+">Proxima</button>"+
"</div></div></div>";
var searchInput=rightContainer.querySelector('#problem-search-input');
if(searchInput){
searchInput.oninput=function(ev){
var value=ev.target.value;
clearTimeout(debounceTimer);
debounceTimer=setTimeout(function(){
state.searchTerm=value;
state.currentPage=1;
renderRightPanel();
var updated=rightContainer.querySelector('#problem-search-input');
if(updated){updated.focus();updated.setSelectionRange(value.length,value.length);}
},400);
};
}
var sevButtons=rightContainer.querySelectorAll('.filter-btn-severity');
for(var i=0;i<sevButtons.length;i++){
(function(btn){
btn.onclick=function(){
state.activeSeverity=btn.getAttribute('data-sev')||'all';
state.currentPage=1;
renderRightPanel();
};
})(sevButtons[i]);
}
var prevBtn=rightContainer.querySelector('#btn-prev');
if(prevBtn){prevBtn.onclick=function(){if(state.currentPage>1){state.currentPage-=1;renderRightPanel();}};}
var nextBtn=rightContainer.querySelector('#btn-next');
if(nextBtn){nextBtn.onclick=function(){if(state.currentPage<totalPages){state.currentPage+=1;renderRightPanel();}};}
var exportBtn=rightContainer.querySelector('#btn-export');
if(exportBtn){exportBtn.onclick=function(){exportCsv(filtered);};}
function fallbackCopy(t){try{var ta=document.createElement('textarea');ta.value=t;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.left='-9999px';ta.style.top='0';ta.style.opacity='0';document.body.appendChild(ta);ta.focus();ta.select();try{ta.setSelectionRange(0,t.length);}catch(e){}try{document.execCommand('copy');}catch(e){}document.body.removeChild(ta);}catch(e){}}
function doCopy(t,btn){var done=function(){btn.classList.add('copied');setTimeout(function(){btn.classList.remove('copied');},900);};try{if(navigator.clipboard&&navigator.clipboard.writeText&&window.isSecureContext){navigator.clipboard.writeText(t).then(done,function(){fallbackCopy(t);done();});}else{fallbackCopy(t);done();}}catch(e){fallbackCopy(t);done();}}
var copyButtons=rightContainer.querySelectorAll('.copy-log-btn');
for(var ci=0;ci<copyButtons.length;ci++){
(function(btn){btn.onclick=function(){var rr=pageItems[+btn.getAttribute('data-idx')];if(!rr)return;var text='['+formatHora(rr.time)+'] '+String(rr.severity).toUpperCase()+' '+rr.origem+' '+rr.traceId+' - '+rr.mensagem;doCopy(text,btn);};})(copyButtons[ci]);
}
}
renderRightPanel();
})();
